def currency_values(text):
    values = []
    source = str(text)
    for symbol in "$£€":
        search_from = 0
        while True:
            symbol_index = source.find(symbol, search_from)
            if symbol_index < 0:
                break
            number_text = ""
            number_started = False
            for character in source[symbol_index + 1:]:
                if character.isdigit():
                    number_text += character
                    number_started = True
                elif character in ".," and number_started:
                    number_text += character
                elif not number_started and character.isspace():
                    continue
                else:
                    break
            cleaned = number_text.replace(",", "").strip(".")
            if cleaned:
                try:
                    values.append(float(cleaned))
                except ValueError:
                    pass
            search_from = symbol_index + 1
    return values

def amount_from_bill(content):
    labels = (
        "total amount due",
        "amount due",
        "balance due",
        "total due",
        "bill total",
        "total cost",
        "total",
        "amount",
        "cost",
        "charge",
    )
    lines = str(content).splitlines() or [str(content)]
    for label in labels:
        found_values = []
        for line in lines:
            lowered = line.lower()
            search_from = 0
            while True:
                label_index = lowered.find(label, search_from)
                if label_index < 0:
                    break
                before_ok = label_index == 0 or not lowered[label_index - 1].isalnum()
                after_index = label_index + len(label)
                after_ok = after_index == len(lowered) or not lowered[after_index].isalnum()
                if before_ok and after_ok:
                    following_text = line[after_index:]
                    marked_values = currency_values(following_text)
                    plain_values = numeric_values(following_text)
                    if marked_values:
                        found_values.append(marked_values[0])
                    elif plain_values:
                        found_values.append(plain_values[0])
                search_from = label_index + len(label)
        unique_values = []
        for value in found_values:
            rounded_value = round(value, 2)
            if rounded_value not in unique_values:
                unique_values.append(rounded_value)
        if len(unique_values) == 1:
            return unique_values[0]
        if unique_values:
            return None
    fallback_values = []
    for value in currency_values(content):
        rounded_value = round(value, 2)
        if rounded_value not in fallback_values:
            fallback_values.append(rounded_value)
    return fallback_values[0] if len(fallback_values) == 1 else None

